bool isPalindrome(const vector<int>& a) {
    int l = 0, r = (int)a.size() - 1;
    while (l < r) {
        if (a[l] != a[r]) return false;   // one mismatch is enough
        ++l; --r;
    }
    return true;   // pointers crossed with no mismatch
}

void rotateLeftOnce(vector<int>& a) {
    if (a.empty()) return;
    int first = a[0];
    for (size_t i = 0; i + 1 < a.size(); ++i)
        a[i] = a[i + 1];          // everything slides left one slot
    a.back() = first;             // the old head wraps to the tail
}

void rotateLeftK(vector<int>& a, int k) {
    if (a.empty()) return;
    k %= (int)a.size();           // rotating by n is a no-op
    for (int step = 0; step < k; ++step)
        rotateLeftOnce(a);        // k passes x n shifts = k*n work
}

