def rotate_left_once(a: list[int]) -> None:
    if not a:
        return
    first = a[0]
    for i in range(len(a) - 1):
        a[i] = a[i + 1]           # everything slides left one slot
    a[-1] = first                 # the old head wraps to the tail


def rotate_left_k(a: list[int], k: int) -> None:
    if not a:
        return
    k %= len(a)                   # rotating by n is a no-op
    for _ in range(k):
        rotate_left_once(a)       # k passes x n shifts = k*n work

