int removeDuplicates(vector<int>& a) {
    if (a.empty()) return 0;
    int write = 1;                       // a[0] is always kept
    for (size_t read = 1; read < a.size(); ++read)
        if (a[read] != a[write - 1])     // compare against last kept value
            a[write++] = a[read];
    return write;                        // count of unique elements
}

