def remove_duplicates(a: list[int]) -> int:
    if not a:
        return 0
    write = 1                            # a[0] is always kept
    for read in range(1, len(a)):
        if a[read] != a[write - 1]:      # compare against last kept value
            a[write] = a[read]
            write += 1
    return write                         # count of unique elements

