vector<int> plusOne(vector<int> d) {
    for (int i = (int)d.size() - 1; i >= 0; --i) {
        if (d[i] < 9) { ++d[i]; return d; }   // no carry out: done
        d[i] = 0;                             // 9 -> 0, carry continues
    }
    d.insert(d.begin(), 1);                   // 999 -> 1000
    return d;
}

