def plus_one(d: list[int]) -> list[int]:
    d = d[:]
    for i in range(len(d) - 1, -1, -1):
        if d[i] < 9:
            d[i] += 1          # no carry out: done
            return d
        d[i] = 0               # 9 -> 0, carry continues
    return [1] + d             # 999 -> 1000

