vector<int> buildArray(const vector<int>& nums) {
    vector<int> out(nums.size());
    for (size_t i = 0; i < nums.size(); ++i)
        out[i] = nums[nums[i]];    // read the index stored at i, then read there
    return out;
}

vector<int> getConcatenation(const vector<int>& nums) {
    size_t n = nums.size();
    vector<int> ans(2 * n);
    for (size_t i = 0; i < n; ++i) {
        ans[i]     = nums[i];
        ans[i + n] = nums[i];    // second half mirrors the first
    }
    return ans;
}

int maximumWealth(const vector<vector<int>>& accounts) {
    int best = 0;
    for (const auto& customer : accounts) {
        int sum = 0;
        for (int money : customer) sum += money;
        best = max(best, sum);       // champion scan across rows
    }
    return best;
}

int dominantIndex(const vector<int>& nums) {
    int best = -1, second = -1, bestIdx = -1;
    for (int i = 0; i < (int)nums.size(); ++i) {
        if (nums[i] > best) {        // new champion; old champion demoted
            second = best;
            best = nums[i];
            bestIdx = i;
        } else if (nums[i] > second) {
            second = nums[i];        // new runner-up only
        }
    }
    return best >= 2 * second ? bestIdx : -1;
}

