def dominant_index(nums: list[int]) -> int:
    best = second = -1
    best_idx = -1
    for i, v in enumerate(nums):
        if v > best:                 # new champion; old champion demoted
            second, best, best_idx = best, v, i
        elif v > second:
            second = v               # new runner-up only
    return best_idx if best >= 2 * second else -1

